!function(){"use strict";function configGeneralCtrl($scope,mS){$scope.data={},$scope.decimales=[2,3,4,5],$scope.getDataTabs=function(codConfig){try{hideLoader(),$scope.codConfig=codConfig,mS.getData("get","Sistema/Get/"+JSON.stringify({codConfig:codConfig}),null,!0).then(response=>{if("0"===response.code&&(hideLoader(),console.log(response)),"1"===response.code)switch(hideLoader(),codConfig){case"CV":$scope.gestionSistema=JSON.parse(response.payload)[0][0],$scope.searchText=$scope.gestionSistema.nombreFiscal,$scope.searchTextArticle=$scope.gestionSistema.descripcion;break;case"CI":$scope.gestionSistema=JSON.parse(response.payload)[0][0],$scope.valoracionMetodos=JSON.parse(response.payload)[0][1],console.log(JSON.parse(response.payload));break;case"CD":$scope.response=JSON.parse(response.payload)[0],$scope.decimalAlmacen=$scope.response.find(item=>"AL"===item.codTransaccion),$scope.decimalVenta=$scope.response.find(item=>"V"===item.codTransaccion),$scope.decimalCompra=$scope.response.find(item=>"C"===item.codTransaccion);break;case"CS":$scope.entidadNotificaciones=JSON.parse(response.payload)[0]}})}catch(error){hideLoader(),console.log(error)}},$scope.getDataTabs("CV")}app.controller("configGeneralCtrl",configGeneralCtrl),configGeneralCtrl.$inject=["$scope","mainService"]}(window.angular);